   100	static bool HdlcByteNeedsEscape(uint8_t aByte)
   101	{
   102	    bool rval;
   103	
   104	    switch (aByte)
   105	    {
   106	    case kFlagXOn:
   107	    case kFlagXOff:
   108	    case kEscapeSequence:
   109	    case kFlagSequence:
   110	    case kFlagSpecial:
   111	        rval = true;
   112	        break;
   113	
   114	    default:
   115	        rval = false;
   116	        break;
   117	    }
   118	
   119	    return rval;
   120	}
   121	
   122	Encoder::Encoder(FrameWritePointer &aWritePointer)
   123	    : mWritePointer(aWritePointer)
   124	    , mFcs(0)
   125	{
   126	}
   127	
   128	otError Encoder::BeginFrame(void)
   129	{
   130	    mFcs = kInitFcs;
   131	
   132	    return mWritePointer.WriteByte(kFlagSequence);
   133	}
   134	
   135	otError Encoder::Encode(uint8_t aByte)
   136	{
   137	    otError error = OT_ERROR_NONE;
   138	
   139	    if (HdlcByteNeedsEscape(aByte))
   140	    {
   141	        VerifyOrExit(mWritePointer.CanWrite(2), error = OT_ERROR_NO_BUFS);
   142	
   143	        mWritePointer.WriteByte(kEscapeSequence);
   144	        mWritePointer.WriteByte(aByte ^ 0x20);
   145	    }
   146	    else
   147	    {
   148	        SuccessOrExit(error = mWritePointer.WriteByte(aByte));
   149	    }
   150	
   151	    mFcs = UpdateFcs(mFcs, aByte);
   152	
   153	exit:
   154	    return error;
   155	}
   156	
   157	otError Encoder::Encode(const uint8_t *aData, uint16_t aLength)
   158	{
   159	    otError           error      = OT_ERROR_NONE;
   160	    uint16_t          oldFcs     = mFcs;
   161	    FrameWritePointer oldPointer = mWritePointer;
   162	
   163	    while (aLength--)
   164	    {
   165	        SuccessOrExit(error = Encode(*aData++));
   166	    }
   167	
   168	exit:
   169	
   170	    if (error != OT_ERROR_NONE)
   171	    {
   172	        mWritePointer = oldPointer;
   173	        mFcs          = oldFcs;
   174	    }
   175	
   176	    return error;
   177	}
   178	
   179	otError Encoder::EndFrame(void)
   180	{
   181	    otError           error      = OT_ERROR_NONE;
   182	    FrameWritePointer oldPointer = mWritePointer;
   183	    uint16_t          oldFcs     = mFcs;
   184	    uint16_t          fcs        = mFcs;
   185	
   186	    fcs ^= 0xffff;
   187	
   188	    SuccessOrExit(error = Encode(fcs & 0xff));
   189	    SuccessOrExit(error = Encode(fcs >> 8));
   190	
   191	    SuccessOrExit(error = mWritePointer.WriteByte(kFlagSequence));
   192	
   193	exit:
   194	
   195	    if (error != OT_ERROR_NONE)
   196	    {
   197	        mWritePointer = oldPointer;
   198	        mFcs          = oldFcs;
   199	    }
   200	
   201	    return error;
   202	}
   203	
   204	Decoder::Decoder(FrameWritePointer &aFrameWritePointer, FrameHandler aFrameHandler, void *aContext)
   205	    : mState(kStateNoSync)
   206	    , mWritePointer(aFrameWritePointer)
   207	    , mFrameHandler(aFrameHandler)
   208	    , mContext(aContext)
   209	    , mFcs(0)
   210	    , mDecodedLength(0)
   211	{
   212	}
   213	
   214	void Decoder::Decode(const uint8_t *aData, uint16_t aLength)
   215	{
   216	    while (aLength--)
   217	    {
   218	        uint8_t byte = *aData++;
   219	
   220	        switch (mState)
   221	        {
   222	        case kStateNoSync:
   223	            if (byte == kFlagSequence)
   224	            {
   225	                mState         = kStateSync;
   226	                mDecodedLength = 0;
   227	                mFcs           = kInitFcs;
   228	            }
   229	
   230	            break;
   231	
   232	        case kStateSync:
   233	            switch (byte)
   234	            {
   235	            case kEscapeSequence:
   236	                mState = kStateEscaped;
   237	                break;
   238	
   239	            case kFlagSequence:
   240	
   241	                if (mDecodedLength > 0)
   242	                {
   243	                    otError error = OT_ERROR_PARSE;
   244	
   245	                    if ((mDecodedLength >= kFcsSize)
   246	#ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   247	                        && (mFcs == kGoodFcs)
   248	#endif
   249	                    )
   250	                    {
   251	                        // Remove the FCS from the frame.
   252	                        mWritePointer.UndoLastWrites(kFcsSize);
   253	                        error = OT_ERROR_NONE;
   254	                    }
   255	
   256	                    mFrameHandler(mContext, error);
   257	                }
   258	
   259	                mDecodedLength = 0;
   260	                mFcs           = kInitFcs;
   261	                break;
   262	
   263	            default:
   264	                if (mWritePointer.CanWrite(sizeof(uint8_t)))
   265	                {
   266	                    mFcs = UpdateFcs(mFcs, byte);
   267	                    mWritePointer.WriteByte(byte);
   268	                    mDecodedLength++;
   269	                }
   270	                else
   271	                {
   272	                    mFrameHandler(mContext, OT_ERROR_NO_BUFS);
   273	                    mState = kStateNoSync;
   274	                }
   275	
   276	                break;
   277	            }
   278	
   279	            break;
   280	
   281	        case kStateEscaped:
   282	            if (mWritePointer.CanWrite(sizeof(uint8_t)))
   283	            {
   284	                byte ^= 0x20;
   285	                mFcs = UpdateFcs(mFcs, byte);
   286	                mWritePointer.WriteByte(byte);
   287	                mDecodedLength++;
   288	                mState = kStateSync;
   289	            }
   290	            else
   291	            {
   292	                mFrameHandler(mContext, OT_ERROR_NO_BUFS);
   293	                mState = kStateNoSync;
   294	            }
   295	
   296	            break;
   297	        }
   298	    }
   299	}
